<template>
  <section class="operation-guide">
    <div class="operation-layout">
      <main v-if="hasLive" v-show="visualMode === 'live'" class="operation-visual operation-live"><div class="operation-panel-heading"><strong>实时摄像头画面</strong><div class="operation-live-actions"><detection-status :status="detectionStatus" /><el-tooltip v-if="automaticStep" content="全部检测条件满足后，自动进入下一步" placement="top"><span class="operation-auto-tag">自动</span></el-tooltip><el-button type="text" @click="visualMode = 'reference'">查看参考图</el-button></div></div><slot name="live" :active="visualMode === 'live'" /></main>
      <main v-show="recordsMode ? visualMode === 'reference' : !hasLive || visualMode === 'reference'" class="operation-visual"><div class="operation-panel-heading"><div class="operation-image-title"><span class="operation-step-counter">{{ stepIndex + 1 }} / {{ steps.length }}</span><strong>{{ step ? step.title : '图像引导' }}</strong></div><el-button v-if="recordsMode || hasLive" type="text" @click="visualMode = recordsMode ? 'evidence' : 'live'">{{ recordsMode ? '返回现场照片' : '返回实时画面' }}</el-button><el-button v-if="image" type="text" icon="el-icon-full-screen" @click="expanded = true">放大查看</el-button></div><div ref="stage" class="operation-image-stage" :class="{ 'has-image': !!image }"><annotated-image v-if="image" :key="imageIdentity" class="operation-image" :style="imageStyle" v-bind="imageContext" :file-id="String(image.file_id)" :visual="image.visual || null" :show-detection="executing" @loaded="imageLoaded" /><div v-else class="operation-image-empty"><i class="el-icon-camera" /><strong>当前步骤暂无参考图片</strong><span>请按照右侧文字要求操作</span></div></div><div class="operation-image-caption"><span><i class="el-icon-picture-outline" /> {{ image && image.caption ? image.caption : '工位区域参考图' }}</span><small>参考图片 · 非实时画面</small></div><div v-if="images.length > 1" class="operation-image-options"><button v-for="(item, i) in images" :key="item.id" :class="{ active: imageIndex === i }" @click="imageIndex = i">{{ item.caption || '参考图 ' + (i + 1) }}</button></div></main>
      <main v-if="recordsMode && visualMode !== 'reference'" class="operation-visual"><div class="operation-panel-heading"><strong>现场留存照片</strong><el-button type="text" @click="visualMode = 'reference'">查看参考图</el-button></div><execution-evidence :execution-id="String(imageContext.executionId)" :position="stepIndex + 1" :photo="evidence" :step="step" /></main>
      <aside class="operation-sidebar" aria-label="步骤流程与操作说明">
        <section class="operation-flow" aria-label="步骤流程"><div class="operation-panel-heading"><strong>步骤流程</strong><span v-if="executing" class="flow-progress" :class="{ complete: completedCount === steps.length }">已完成 {{ completedCount }}/{{ steps.length }}</span><span v-else>{{ steps.length }} 步</span></div><nav aria-label="作业步骤流程"><button v-for="(item, i) in steps" :key="item.id" :class="{ active: stepIndex === i, confirmed: confirmed[i] }" :disabled="navigationLocked && stepIndex !== i" :aria-current="stepIndex === i ? 'step' : null" @click="select(i)"><span class="flow-number"><i v-if="confirmed[i]" class="el-icon-check" /><template v-else>{{ i + 1 }}</template></span><span class="flow-text"><strong>{{ item.title }}</strong><small :class="'timing-' + stepTiming(i).type">{{ stepTiming(i).text }}</small></span><i v-if="stepIndex === i" class="el-icon-arrow-right" /></button></nav></section>
        <section class="operation-instructions" aria-label="操作说明"><div class="operation-panel-heading"><strong>操作说明</strong><i class="el-icon-document" /></div><div v-if="step" class="operation-instruction-body"><section><p>{{ step.instruction || '暂无操作说明' }}</p></section><section v-if="stepVoiceError" class="instruction-warning" role="status"><p>{{ stepVoiceError }}</p><el-button type="text" @click="checkStepVoice(true)">重播语音</el-button></section><section v-if="timeoutVoiceError" class="instruction-warning" role="status"><p>{{ timeoutVoiceError }}</p><el-button type="text" @click="checkTimeoutVoice(true)">重播提醒</el-button></section><section class="instruction-parameters"><h3>步骤参数</h3><dl><template v-for="param in stepParameters"><dt :key="param.label + '-label'">{{ param.label }}</dt><dd :key="param.label">{{ param.value }}</dd></template></dl></section><section v-if="detectionRequirements.length" class="instruction-detection"><h3>检测要求</h3><div v-for="(requirement, r) in detectionRequirements" :key="requirement.id" class="instruction-target"><strong v-if="detectionRequirements.length > 1">区域 {{ r + 1 }}</strong><p v-for="line in requirement.lines" :key="line">{{ line }}</p></div></section><section v-if="step.precautions" class="instruction-warning"><h3><i class="el-icon-warning-outline" />注意事项</h3><p>{{ step.precautions }}</p></section><section v-if="step.check_requirements"><h3><i class="el-icon-circle-check" />检查要求</h3><p>{{ step.check_requirements }}</p></section><section v-if="step.workplace_requirements"><h3><i class="el-icon-office-building" />环境要求</h3><p>{{ step.workplace_requirements }}</p></section><section v-if="step.resource_requirements && step.resource_requirements.length"><h3><i class="el-icon-set-up" />工具与设备</h3><p v-for="req in step.resource_requirements" :key="req.model_id">{{ req.name }}<small v-if="req.specification"> · {{ req.specification }}</small> × {{ req.quantity }} {{ req.unit }}<span v-if="req.description">；{{ req.description }}</span></p></section></div></section>
      </aside>
    </div>
    <footer class="operation-controls"><div class="operation-control-note"><slot name="status"><i class="el-icon-info" />按步骤查看图像与文字指导</slot></div><div class="operation-control-buttons"><el-button v-if="!navigationLocked" :disabled="stepIndex === 0" icon="el-icon-arrow-left" @click="select(stepIndex - 1)">上一步</el-button><slot name="confirm" /><el-button v-if="!navigationLocked" :disabled="stepIndex >= steps.length - 1" @click="select(stepIndex + 1)">下一步<i class="el-icon-arrow-right el-icon--right" /></el-button></div></footer>
    <el-dialog title="图像引导" :visible.sync="expanded" fullscreen append-to-body><div v-if="expanded && image" class="operation-expanded"><annotated-image :key="imageIdentity" class="operation-expanded-image" v-bind="imageContext" :file-id="String(image.file_id)" :visual="image.visual || null" :show-detection="executing" /></div></el-dialog>
  </section>
</template>
<script src="../js/operation_guide.js" />
<style scoped lang="scss" src="../styles/operation_guide.scss" />
